export const KEY='suming-cozy-island-v1';
export const FURNITURE={bench:{name:'쿠션 벤치',max:3},pot:{name:'토분 화분',max:10},tree:{name:'사과나무',max:4},bowl:{name:'모모 물그릇',max:2},pond:{name:'수련 연못',max:2},table:{name:'티 테이블',max:3},cushion:{name:'폭신 방석',max:4},lamp:{name:'정원등',max:5},path:{name:'디딤돌',max:20},fence:{name:'나무 울타리',max:10}};
export const SEEDS={daisy:'데이지',tulip:'튤립',lavender:'라벤더'};
export const CLOSET={skin:['cream','honey','cocoa'],hair:['bob','wave','short','twin'],hairColor:['chestnut','black','caramel','rose'],top:['sailor','cardigan','tee','hoodie','blouse','overall'],bottom:['shorts','skirt','trousers','pleats'],shoes:['cream','brown','pink','sage'],hat:['none','straw','beret','bow'],accessory:['none','bag','scarf','glasses']};
export const LABELS={cream:'크림',honey:'허니',cocoa:'코코아',bob:'단정한 단발',wave:'물결 머리',short:'산뜻한 숏컷',twin:'양갈래',chestnut:'밤색',black:'흑갈색',caramel:'카라멜',rose:'로즈 브라운',sailor:'바다 세일러',cardigan:'봄 가디건',tee:'산책 티셔츠',hoodie:'포근 후디',blouse:'리본 블라우스',overall:'정원 멜빵',shorts:'반바지',skirt:'꽃잎 스커트',trousers:'면바지',pleats:'주름 치마',brown:'브라운',pink:'딸기 우유',sage:'세이지',none:'착용 안 함',straw:'밀짚 모자',beret:'딸기 베레모',bow:'리본 머리띠',bag:'작은 크로스백',scarf:'체크 스카프',glasses:'동그란 안경'};
export const defaultOutfit=()=>({skin:'cream',hair:'bob',hairColor:'chestnut',top:'sailor',bottom:'shorts',shoes:'brown',hat:'none',accessory:'bag'});
export function validCell(c,r){return Number.isInteger(c)&&Number.isInteger(r)&&c>=0&&r>=0&&c<9&&r<9&&(c-4)**2+(r-4)**2<=20&&!(c>=1&&c<=3&&r>=1&&r<=3);}
export function fresh(){return{v:1,next:9,avatar:[4,7],outfit:defaultOutfit(),items:[{id:1,kind:'bench',c:2,r:6,rot:0},{id:2,kind:'pot',c:5,r:3,rot:0},{id:3,kind:'pot',c:6,r:4,rot:0},{id:4,kind:'tree',c:7,r:2,rot:0},{id:5,kind:'bowl',c:5,r:7,rot:0},{id:6,kind:'pond',c:7,r:5,rot:0},{id:7,kind:'path',c:4,r:4,rot:0},{id:8,kind:'path',c:4,r:5,rot:0}],flowers:[],hearts:0,petAt:0,fruitAt:0,apples:0,water:false,welcomed:false,theme:'day',tasks:{},looks:[]};}
export function growth(p,now=Date.now()){return p.seed?Math.min(1,Math.max(0,(Math.max(0,now-p.planted)+(p.boost||0))/90000)):0;}
export const passable=(s,c,r)=>validCell(c,r)&&!s.items.some(p=>p.c===c&&p.r===r&&p.kind!=='path');
export function route(s,start,goal){if(!Array.isArray(goal)||goal.length!==2||!passable(s,...goal))return[];const q=[[start]],seen=new Set([start.join(',')]);while(q.length){const path=q.shift(),[c,r]=path.at(-1);if(c===goal[0]&&r===goal[1])return path;for(const n of [[c+1,r],[c-1,r],[c,r+1],[c,r-1]]){const k=n.join(',');if(!seen.has(k)&&passable(s,...n)){seen.add(k);q.push([...path,n]);}}}return[];}
export function approach(s,start,p){const targets=[[p.c,p.r+1],[p.c+1,p.r],[p.c-1,p.r],[p.c,p.r-1]].map(t=>route(s,start,t)).filter(t=>t.length);return targets.sort((a,b)=>a.length-b.length)[0]||[];}
export function apply(s,e,now=Date.now()){const n=structuredClone(s),p=n.items.find(p=>p.id===e.id),fail=why=>({ok:false,why,state:s});
 if(e.type==='wear'){if(!CLOSET[e.slot]?.includes(e.value))return fail('아직 없는 코디예요.');n.outfit[e.slot]=e.value;n.tasks.dressed=true;}
 else if(e.type==='look-save'){n.looks=[structuredClone(n.outfit),...n.looks.filter(x=>JSON.stringify(x)!==JSON.stringify(n.outfit))].slice(0,4);}
 else if(e.type==='look-load'){const look=n.looks[e.index];if(!look)return fail('저장한 코디가 없어요.');n.outfit=structuredClone(look);}
 else if(e.type==='walk'){if(!route(s,s.avatar,e.to).length)return fail('그쪽으로 가는 길이 없어요.');n.avatar=e.to;}
 else if(e.type==='place'||e.type==='move'){const kind=e.type==='move'?p?.kind:e.kind;if(!FURNITURE[kind]||!validCell(e.c,e.r))return fail('잔디 안의 빈 자리를 골라 주세요.');if(n.items.some(x=>x.c===e.c&&x.r===e.r&&x.id!==p?.id)||n.avatar[0]===e.c&&n.avatar[1]===e.r)return fail('물건이나 내가 있는 자리예요.');if(e.type==='place'&&n.items.filter(x=>x.kind===kind).length>=FURNITURE[kind].max)return fail('주머니의 물건을 모두 놓았어요.');const item=e.type==='move'?p:{id:n.next++,kind,rot:0};item.c=e.c;item.r=e.r;if(e.type==='place')n.items.push(item);if(![[0,1],[1,0],[-1,0],[0,-1]].some(([dc,dr])=>passable(n,n.avatar[0]+dc,n.avatar[1]+dr)))return fail('걸어 다닐 길을 한 칸 남겨 주세요.');n.tasks.decorated=true;}
 else if(e.type==='rotate'){if(!p)return fail('물건을 골라 주세요.');p.rot=1-p.rot;}
 else if(e.type==='store'){if(!p)return fail('물건을 골라 주세요.');if(p.seed)return fail('심은 화분은 옮겨 주세요. 꽃을 지우지 않아요.');n.items=n.items.filter(x=>x.id!==p.id);}
 else if(['plant','water','fill','harvest','sit'].includes(e.type)){
 if(!p||Math.abs(s.avatar[0]-p.c)+Math.abs(s.avatar[1]-p.r)!==1)return fail('먼저 물건 가까이 가 주세요.');
 if(e.type==='plant'){if(p.kind!=='pot'||p.seed||!SEEDS[e.seed])return fail('빈 화분을 골라 주세요.');p.seed=e.seed;p.planted=now;p.boost=0;p.watered=0;n.tasks.planted=true;}
 if(e.type==='water'){if(p.kind!=='pot'||!p.seed)return fail('씨앗을 심은 화분에 물을 주어요.');if(growth(p,now)>=1){if(!n.flowers.includes(p.seed))n.flowers.push(p.seed);return{ok:true,state:n,why:'도감에 꽃을 기록했어요.'};}if(p.watered&&now-p.watered<7000)return fail('물이 스며들고 있어요. 잠시 쉬어 주세요.');p.watered=now;p.boost=(p.boost||0)+30000;n.tasks.watered=true;}
 if(e.type==='fill'){if(p.kind!=='bowl')return fail('물그릇을 골라 주세요.');n.water=true;n.tasks.filled=true;}
 if(e.type==='harvest'){if(p.kind!=='tree')return fail('사과나무를 골라 주세요.');if(n.fruitAt&&now-n.fruitAt<60000)return fail('다음 사과가 익고 있어요.');n.fruitAt=now;n.apples++;n.tasks.harvested=true;}
 if(e.type==='sit'){if(!['bench','cushion'].includes(p.kind))return fail('앉을 자리를 골라 주세요.');n.tasks.rested=true;}}
 else if(e.type==='pet'){if(n.petAt&&now-n.petAt<10000)return fail('모모가 가르릉거리며 쉬고 있어요.');n.petAt=now;n.hearts=Math.min(10,n.hearts+1);n.tasks.friend=true;}
 else if(e.type==='theme'){if(!['day','sunset'].includes(e.value))return fail('없는 풍경이에요.');n.theme=e.value;}
 else if(e.type==='welcome')n.welcomed=true;else return fail('아직 할 수 없어요.');return{ok:true,state:n};}
export function restore(raw){try{const d=JSON.parse(raw);if(d.v!==1||!Array.isArray(d.items)||d.items.length>75)return fresh();const s=fresh();s.items=[];const ids=new Set();for(const p of d.items){if(!FURNITURE[p.kind]||!validCell(p.c,p.r)||!Number.isSafeInteger(p.id)||p.id<1||ids.has(p.id)||s.items.some(x=>x.c===p.c&&x.r===p.r)||s.items.filter(x=>x.kind===p.kind).length>=FURNITURE[p.kind].max)continue;ids.add(p.id);s.items.push({id:p.id,kind:p.kind,c:p.c,r:p.r,rot:p.rot===1?1:0,...(p.kind==='pot'&&SEEDS[p.seed]&&Number.isFinite(p.planted)?{seed:p.seed,planted:p.planted,boost:Math.max(0,Math.min(90000,Number(p.boost)||0)),watered:Number(p.watered)||0}:{})});}s.next=Math.max(0,...ids)+1;if(Array.isArray(d.avatar)&&passable(s,...d.avatar))s.avatar=d.avatar;else{const cells=[];for(let r=0;r<9;r++)for(let c=0;c<9;c++)if(passable(s,c,r))cells.push([c,r]);s.avatar=cells[0]||[4,7];}for(const k in CLOSET)if(CLOSET[k].includes(d.outfit?.[k]))s.outfit[k]=d.outfit[k];s.looks=Array.isArray(d.looks)?d.looks.slice(0,4).filter(x=>Object.keys(CLOSET).every(k=>CLOSET[k].includes(x[k]))):[];s.flowers=Array.isArray(d.flowers)?d.flowers.filter(x=>SEEDS[x]):[];s.hearts=Math.max(0,Math.min(10,Math.floor(Number(d.hearts)||0)));for(const k of ['petAt','fruitAt','apples'])s[k]=Math.max(0,Number(d[k])||0);s.water=d.water===true;s.welcomed=d.welcomed===true;s.theme=d.theme==='sunset'?'sunset':'day';s.tasks=d.tasks&&typeof d.tasks==='object'?Object.fromEntries(Object.entries(d.tasks).filter(([k,v])=>['dressed','decorated','planted','watered','filled','harvested','rested','friend'].includes(k)&&v===true)):{};return s;}catch{return fresh();}}
